// ── O(1) — constant: result in one step regardless of size ───────
function getFirst(arr) {
  return arr[0]; // direct index — one operation
}

const map = new Map([['alice', 42], ['bob', 7]]);
map.get('alice'); // O(1) average — hash function + bucket lookup

// ── O(log n) — binary search on a sorted array ────────────────────
// Each iteration halves the search space.
// For n = 1,000,000 entries we need at most log2(1000000) ≈ 20 iterations.
function binarySearch(sorted, target) {
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1; // unsigned right-shift = safe floor divide by 2
    if (sorted[mid] === target) return mid;  // found
    if (sorted[mid] < target)   lo = mid + 1; // target is in right half
    else                        hi = mid - 1; // target is in left half
  }
  return -1; // not found
}
console.log(binarySearch([1, 3, 5, 7, 9, 11], 7)); // 3

// ── O(n) — linear scan: must visit every element at least once ───
function sumAll(arr) {
  return arr.reduce((acc, x) => acc + x, 0); // n additions
}

// ── O(n^2) — naive duplicate check: nested loops ──────────────────
// For n = 10000 items: ~50,000,000 comparisons.
function hasDuplicateNaive(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++) // triangular — n*(n-1)/2 pairs
      if (arr[i] === arr[j]) return true;
  return false;
}

// ── O(n) — Set-based duplicate check: hash replaces inner loop ───
// Same correctness, n lookups each O(1) → total O(n) time, O(n) space.
function hasDuplicateFast(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true; // O(1) lookup
    seen.add(x);                  // O(1) insert
  }
  return false;
}

const nums = [3, 1, 4, 1, 5, 9, 2, 6];
console.log(hasDuplicateNaive(nums)); // true
console.log(hasDuplicateFast(nums));  // true

// ── Demonstrating the key complexity patterns ─────────────────────

// PATTERN 1: O(n log n) — merge sort (classic divide-and-conquer)
// T(n) = 2 * T(n/2) + O(n)  →  Master Theorem: O(n log n)
function mergeSort(arr) {
  if (arr.length <= 1) return arr;             // base case: already sorted
  const mid = Math.floor(arr.length / 2);
  const left  = mergeSort(arr.slice(0, mid));  // T(n/2)
  const right = mergeSort(arr.slice(mid));     // T(n/2)
  return merge(left, right);                   // O(n) merge step
}

function merge(a, b) {
  const result = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {       // linear scan of both halves
    result.push(a[i] <= b[j] ? a[i++] : b[j++]);
  }
  return result.concat(a.slice(i)).concat(b.slice(j));
}

console.log(mergeSort([5, 2, 8, 1, 9, 3])); // [1, 2, 3, 5, 8, 9]

// PATTERN 2: exponential — naive Fibonacci (BAD): O(2^n), precisely Θ(1.618^n)
// fib(5) calls fib(4) and fib(3); fib(4) calls fib(3) and fib(2);
// fib(3) is computed TWICE — exponential redundancy.
function fibNaive(n) {
  if (n <= 1) return n;
  return fibNaive(n - 1) + fibNaive(n - 2); // 2 recursive calls per level
}

// PATTERN 3: O(n) — memoised Fibonacci (GOOD)
// Each sub-problem computed once and cached. O(n) time, O(n) space.
function fibMemo(n, cache = {}) {
  if (n <= 1) return n;
  if (cache[n] !== undefined) return cache[n]; // cache hit: O(1)
  cache[n] = fibMemo(n - 1, cache) + fibMemo(n - 2, cache);
  return cache[n];
}

console.log(fibNaive(10)); // 55 (slow for large n)
console.log(fibMemo(10));  // 55 (fast even for n=1000 — though results past n=78 exceed 2^53 and are rounded)

// PATTERN 4: O(n log n) — two-sum via sort + two pointers
// Alternative: O(n) with a Map (shown below)
function twoSumSorted(arr, target) {
  const sorted = [...arr].sort((a, b) => a - b); // O(n log n)
  let lo = 0, hi = sorted.length - 1;
  while (lo < hi) {                              // O(n) scan
    const sum = sorted[lo] + sorted[hi];
    if (sum === target) return [sorted[lo], sorted[hi]];
    if (sum < target) lo++; else hi--;
  }
  return null;
}

function twoSumMap(arr, target) {               // O(n) time, O(n) space
  const seen = new Map();
  for (const x of arr) {
    const complement = target - x;
    if (seen.has(complement)) return [complement, x];
    seen.set(x, true);
  }
  return null;
}

console.log(twoSumMap([2, 7, 11, 15], 9)); // [2, 7]

// ── Complexity cheat-sheet with concrete numbers ─────────────────
//
// Class       | n=10    n=1000   n=1,000,000  |
// ────────────────────────────────────────────────────────────────
// O(1)        | 1       1        1            | constant
// O(log n)    | 3       10       20           | binary search
// O(n)        | 10      1000     1,000,000    | linear scan
// O(n log n)  | 33      10000    20,000,000   | merge sort
// O(n^2)      | 100     1M       10^12        | nested loops
// O(2^n)      | 1024    2^1000   astronomical | all subsets
//
// ── Dropping constants and lower-order terms ─────────────────────
const examples = [
  { expression: '5*n**2 + 100*n + 7', simplifies: 'O(n^2)' },
  { expression: '3*n + 2',            simplifies: 'O(n)' },
  { expression: '2**n + n**100',      simplifies: 'O(2^n)' }, // exponential beats polynomial
  { expression: 'n*log2(n) + n',      simplifies: 'O(n log n)' },
];

// ── Deriving complexity from code structure ───────────────────────

// Sequential blocks — take the dominant term
function sequential(n) {
  // Block A: O(n)
  for (let i = 0; i < n; i++) { /* O(1) work */ }
  // Block B: O(n^2)
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++) { /* O(1) work */ }
  // Total: O(n) + O(n^2) = O(n^2)  — dominated by the quadratic block
}

// Hidden O(n) inside a loop → total O(n^2)
function hiddenQuadratic(arr) {
  for (const x of arr) {           // n iterations
    if (arr.indexOf(x + 1) >= 0) { // indexOf is O(n) ← HIDDEN COST
      console.log(x);
    }
  }
  // Looks like O(n) but is actually O(n^2). Fix: convert arr to a Set first.
}

// Fixed version: O(n) time, O(n) space
function fixedLinear(arr) {
  const set = new Set(arr);         // O(n) to build
  for (const x of arr) {           // n iterations
    if (set.has(x + 1)) {          // O(1) lookup
      console.log(x);
    }
  }
  // Total: O(n) + O(n) = O(n)
}
